import {
  fieldCardSchema,
  placeSchema,
  searchResultSchema,
  type FieldCard,
  type FieldCardRequest,
  type Location,
  type PlaceDetails,
} from '../shared/contract.ts'

const CACHE_KEY = 'trail-sketch.last-card'

async function readError(response: Response): Promise<string> {
  const payload = (await response.json().catch(() => null)) as { error?: string } | null
  return payload?.error ?? 'request_failed'
}

export async function searchPlaces(query: string): Promise<Location[]> {
  const response = await fetch(`/api/search?q=${encodeURIComponent(query)}`)
  if (!response.ok) throw new Error(await readError(response))
  const parsed = searchResultSchema.safeParse(await response.json())
  if (!parsed.success) throw new Error('request_failed')
  return parsed.data.results
}

export async function loadPlace(latitude: number, longitude: number): Promise<PlaceDetails> {
  const params = new URLSearchParams({
    latitude: String(latitude),
    longitude: String(longitude),
  })
  const response = await fetch(`/api/place?${params}`)
  if (!response.ok) throw new Error(await readError(response))
  const parsed = placeSchema.safeParse(await response.json())
  if (!parsed.success) throw new Error('request_failed')
  return parsed.data
}

export async function requestFieldCard(body: FieldCardRequest): Promise<FieldCard> {
  const response = await fetch('/api/field-card', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  })
  if (!response.ok) throw new Error(await readError(response))
  const parsed = fieldCardSchema.safeParse(await response.json())
  if (!parsed.success) throw new Error('card_unreadable')
  return parsed.data
}

export async function requestNarration(spokenScript: string): Promise<Blob> {
  const response = await fetch('/api/narrate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ spokenScript }),
  })
  if (!response.ok) throw new Error(await readError(response))
  return response.blob()
}

export function readCachedCard(): FieldCard | null {
  try {
    const raw = localStorage.getItem(CACHE_KEY)
    if (!raw) return null
    const parsed = fieldCardSchema.safeParse(JSON.parse(raw))
    return parsed.success && parsed.data.source === 'gemma' ? parsed.data : null
  } catch {
    return null
  }
}

export function writeCachedCard(card: FieldCard): void {
  if (card.source !== 'gemma') return
  localStorage.setItem(CACHE_KEY, JSON.stringify(card))
}

export const errorCopy: Record<string, string> = {
  missing_gemma_key: 'The live study needs a Gemma key on the server. This sheet is a sample.',
  missing_elevenlabs_key: 'Narration needs an ElevenLabs key on the server.',
  gemma_rejected: 'Gemma refused the key. Check GEMMA_API_KEY.',
  elevenlabs_rejected: 'ElevenLabs refused the key. Check ELEVENLABS_API_KEY.',
  gemma_failed: 'Gemma did not answer. Try the study again.',
  elevenlabs_failed: 'The reading did not come back. Try again.',
  card_unreadable: 'The study came back in a shape the sheet could not use.',
  geocode_failed: 'The place name could not be looked up.',
  rate_limited: 'Too many studies in a short while. Wait a minute.',
  request_failed: 'The trail connection dropped.',
  query_too_short: 'Type a little more of the place name.',
  invalid_coordinates: 'That point is not a real location.',
}

import maplibregl from 'maplibre-gl'
import 'maplibre-gl/dist/maplibre-gl.css'
import { useEffect, useRef } from 'react'
import type { Location } from '../../shared/contract.ts'
import type { Spot } from '../data/spots.ts'

type MapViewProps = {
  spots: Spot[]
  selected: Location | null
  onSelect: (location: Location) => void
}

export function MapView({ spots, selected, onSelect }: MapViewProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const mapRef = useRef<maplibregl.Map | null>(null)
  const markersRef = useRef<maplibregl.Marker[]>([])
  const onSelectRef = useRef(onSelect)

  useEffect(() => {
    onSelectRef.current = onSelect
  }, [onSelect])

  useEffect(() => {
    const container = containerRef.current
    if (!container || mapRef.current) return

    const map = new maplibregl.Map({
      container,
      style: 'https://tiles.openfreemap.org/styles/liberty',
      center: [10, 28],
      zoom: 1.5,
      attributionControl: true,
    })
    map.addControl(new maplibregl.NavigationControl({ showCompass: false }), 'bottom-right')
    map.on('click', (event) => {
      onSelectRef.current({
        longitude: event.lngLat.lng,
        latitude: event.lngLat.lat,
        name: 'This spot',
      })
    })
    mapRef.current = map

    return () => {
      markersRef.current.forEach((marker) => marker.remove())
      markersRef.current = []
      map.remove()
      mapRef.current = null
    }
  }, [])

  useEffect(() => {
    const map = mapRef.current
    if (!map) return

    markersRef.current.forEach((marker) => marker.remove())
    markersRef.current = spots.map((spot) => {
      const dot = document.createElement('button')
      dot.type = 'button'
      dot.className = 'pin'
      dot.title = spot.name
      dot.setAttribute('aria-label', spot.name)
      const active =
        selected !== null &&
        Math.abs(selected.longitude - spot.longitude) < 0.0001 &&
        Math.abs(selected.latitude - spot.latitude) < 0.0001
      if (active) dot.classList.add('is-active')
      dot.addEventListener('click', (event) => {
        event.stopPropagation()
        onSelectRef.current({
          longitude: spot.longitude,
          latitude: spot.latitude,
          name: spot.name,
        })
      })
      return new maplibregl.Marker({ element: dot }).setLngLat([spot.longitude, spot.latitude]).addTo(map)
    })
  }, [spots, selected])

  useEffect(() => {
    const map = mapRef.current
    if (!map || !selected) return
    map.flyTo({
      center: [selected.longitude, selected.latitude],
      zoom: Math.max(map.getZoom(), 13),
      essential: true,
    })
  }, [selected])

  return <div ref={containerRef} className="map" />
}

import { useCallback, useEffect, useRef, useState, type FormEvent } from 'react'
import {
  errorCopy,
  loadPlace,
  readCachedCard,
  requestFieldCard,
  requestNarration,
  searchPlaces,
  writeCachedCard,
} from './api.ts'
import { spots } from './data/spots.ts'
import { MapView } from './map/MapView.tsx'
import { FieldSheet } from './sheet/FieldSheet.tsx'
import {
  mediumLabels,
  mediums,
  usesPigment,
  type FieldCard,
  type Location,
  type Medium,
} from '../shared/contract.ts'

function sampleCard(location: Location, medium: Medium, sky: string): FieldCard {
  const pigment = usesPigment(medium)
  return {
    placeName: location.name,
    longitude: location.longitude,
    latitude: location.latitude,
    medium,
    motif: pigment ? 'A color mass against a quiet ground' : 'One dark shape against a light field',
    values: ['Lit edge', 'Middle tone', 'The darkest note'],
    palette: pigment ? ['#d4532b', '#1f6b56', '#2f4d6e'] : [],
    subject:
      'This is a sample so the sheet has a shape before a live study. Stand where you will work, then write it again once Gemma is connected.',
    leaveBefore: 'Leave when the shadow of your hand crosses the motif.',
    spokenScript: `You are at ${location.name}. Look for one lit edge, a middle tone, and a single dark note. Draw or paint that, then put the phone away.`,
    weatherLine: sky || 'Light not read yet',
    generatedAt: new Date().toISOString(),
    source: 'sample',
  }
}

export default function App() {
  const [medium, setMedium] = useState<Medium>('graphite')
  const [selected, setSelected] = useState<Location | null>(null)
  const [card, setCard] = useState<FieldCard | null>(null)
  const [weather, setWeather] = useState('')
  const [notice, setNotice] = useState<string | null>(null)
  const [query, setQuery] = useState('')
  const [results, setResults] = useState<Location[]>([])
  const [busy, setBusy] = useState<'card' | 'voice' | 'search' | null>(null)
  const [saved] = useState<FieldCard | null>(() => readCachedCard())
  const audioRef = useRef<HTMLAudioElement | null>(null)
  const audioUrl = useRef<string | null>(null)
  const chooseId = useRef(0)

  useEffect(() => {
    return () => {
      if (audioUrl.current) URL.revokeObjectURL(audioUrl.current)
    }
  }, [])

  const choose = useCallback(async (location: Location) => {
    const id = chooseId.current + 1
    chooseId.current = id
    setSelected(location)
    setCard(null)
    setNotice(null)
    setResults([])
    setWeather('')
    try {
      const place = await loadPlace(location.latitude, location.longitude)
      if (chooseId.current !== id) return
      setSelected({
        longitude: location.longitude,
        latitude: location.latitude,
        name: location.name === 'This spot' ? place.name : location.name,
      })
      setWeather(place.weatherLine)
    } catch (error) {
      if (chooseId.current !== id) return
      const code = error instanceof Error ? error.message : 'request_failed'
      setNotice(errorCopy[code] ?? errorCopy.request_failed)
    }
  }, [])

  async function onSearch(event: FormEvent) {
    event.preventDefault()
    const trimmed = query.trim()
    if (trimmed.length < 2) return
    setBusy('search')
    setNotice(null)
    try {
      setResults(await searchPlaces(trimmed))
    } catch (error) {
      const code = error instanceof Error ? error.message : 'request_failed'
      setNotice(errorCopy[code] ?? errorCopy.request_failed)
      setResults([])
    } finally {
      setBusy(null)
    }
  }

  function locate() {
    if (!navigator.geolocation) {
      setNotice('This browser cannot share a location.')
      return
    }
    navigator.geolocation.getCurrentPosition(
      (position) => {
        void choose({
          longitude: position.coords.longitude,
          latitude: position.coords.latitude,
          name: 'This spot',
        })
      },
      () => setNotice('Location stayed off. Search a place or tap the map.'),
      { enableHighAccuracy: true, timeout: 8000 },
    )
  }

  async function writeStudy() {
    if (!selected) return
    setBusy('card')
    setNotice(null)
    try {
      const next = await requestFieldCard({ ...selected, medium })
      setCard(next)
      writeCachedCard(next)
    } catch (error) {
      const code = error instanceof Error ? error.message : 'request_failed'
      if (code === 'missing_gemma_key') {
        setCard(sampleCard(selected, medium, weather))
      }
      setNotice(errorCopy[code] ?? errorCopy.request_failed)
    } finally {
      setBusy(null)
    }
  }

  async function listen() {
    if (!card) return
    setBusy('voice')
    setNotice(null)
    try {
      const blob = await requestNarration(card.spokenScript)
      if (audioUrl.current) URL.revokeObjectURL(audioUrl.current)
      const url = URL.createObjectURL(blob)
      audioUrl.current = url
      if (!audioRef.current) audioRef.current = new Audio()
      audioRef.current.src = url
      await audioRef.current.play()
    } catch (error) {
      const code = error instanceof Error ? error.message : 'request_failed'
      setNotice(errorCopy[code] ?? errorCopy.request_failed)
    } finally {
      setBusy(null)
    }
  }

  function changeMedium(next: Medium) {
    setMedium(next)
    setCard(null)
  }

  return (
    <div className="app">
      <header className="bar">
        <div className="brand">
          <p className="mark">Trail Sketch</p>
          <p className="tag">A field study for drawing and painting</p>
        </div>
        <form className="search" onSubmit={onSearch}>
          <label className="sr" htmlFor="place-search">
            Search a place
          </label>
          <input
            id="place-search"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Park, river, overlook"
            autoComplete="off"
          />
          <button type="submit" disabled={busy === 'search'}>
            {busy === 'search' ? '…' : 'Find'}
          </button>
        </form>
        <div className="mediums" role="radiogroup" aria-label="Medium">
          {mediums.map((item) => (
            <button
              key={item}
              type="button"
              role="radio"
              aria-checked={medium === item}
              className={medium === item ? 'is-on' : ''}
              onClick={() => changeMedium(item)}
            >
              {mediumLabels[item]}
            </button>
          ))}
        </div>
        <div className="bar-actions">
          <button type="button" className="locate" onClick={locate}>
            I am here
          </button>
          {saved && !selected ? (
            <button
              type="button"
              className="locate"
              onClick={() => {
                setMedium(saved.medium)
                setSelected({
                  name: saved.placeName,
                  longitude: saved.longitude,
                  latitude: saved.latitude,
                })
                setCard(saved)
                setWeather(saved.weatherLine)
              }}
            >
              Saved study
            </button>
          ) : null}
        </div>
      </header>

      {results.length > 0 ? (
        <ul className="results">
          {results.map((place) => (
            <li key={`${place.longitude}-${place.latitude}`}>
              <button type="button" onClick={() => void choose(place)}>
                {place.name}
              </button>
            </li>
          ))}
        </ul>
      ) : null}

      {notice && !selected ? <p className="toast">{notice}</p> : null}

      <MapView spots={spots} selected={selected} onSelect={(location) => void choose(location)} />

      {selected ? (
        <FieldSheet
          location={selected}
          medium={medium}
          card={card}
          weatherLine={weather}
          notice={notice}
          busy={busy === 'card' || busy === 'voice' ? busy : null}
          onClose={() => {
            setSelected(null)
            setCard(null)
            setNotice(null)
          }}
          onWrite={() => void writeStudy()}
          onListen={() => void listen()}
        />
      ) : (
        <p className="hint">Tap a pigment dot, search a place, or stand where you will draw.</p>
      )}
    </div>
  )
}

